/*
 * Blog content for /blog/[slug]. Hand-written (not generated by scripts/convert.mjs).
 *
 * Castle Rock, CO (November 2026): the blog ships with NO posts. None of the McAllen articles is carried over (they were
 * written for McAllen's climate, store and neighbouring cities) and nothing is written for Castle Rock until the client
 * supplies it: /blog renders the "New articles coming soon" state (components/blog/pages.tsx), the header shows Blog as a
 * plain link (lib/blog-nav.ts) and app/(en)/blog/[slug] is absent until the first article (restore it from the McAllen
 * repo together with components/blog/pages.tsx PostPage, which stays). Add a post here and everything else — cards,
 * header dropdown, sitemap entries, llms.txt, JSON-LD — follows. The McAllen slugs 308 to /blog (vercel.json).
 *
 * Inline links use [text](href) inside a paragraph — rendered by components/blog/Rich.tsx.
 */

export type BlogImage = { src: string; alt: string; width: number; height: number };

/** a data table inside a section (the size guide, October 27, 2026): scrolls horizontally on narrow screens */
export type BlogTable = { caption?: string; head: string[]; rows: string[][]; note?: string };
/** the store block after the FAQ ("Visit Snooze Mattress in Castle Rock"): heading, lines (inline links allowed), fine print */
export type BlogVisit = { heading: string; lines: string[]; fine?: string };

export type BlogSection = {
  heading?: string; // rendered as <h2>; the intro has none
  paragraphs: string[];
  table?: BlogTable; // rendered after the paragraphs, before the image
  image?: BlogImage & { caption?: string }; // supporting image shown after the section
};

export type BlogFaq = { question: string; answer: string };
export type BlogSource = { label: string; href: string }; // cited source, rendered under the article

export type BlogPost = {
  slug: string;
  title: string; // <h1> + BlogPosting.headline
  metaTitle: string; // < 60 chars
  metaDescription: string; // < 160 chars
  keywords: string[];
  datePublished: string; // ISO date
  dateModified?: string; // ISO date of the last content refresh (BlogPosting.dateModified, og:modified_time, sitemap lastmod)
  dateDisplay: string; // as given by the client
  readTime: string; // as given by the client
  featured: BlogImage;
  featuredFit?: 'contain'; // show the whole featured image instead of cropping it to the banner height
  excerpt: string; // first sentence of the post, verbatim — used on cards
  sections: BlogSection[];
  faqs: BlogFaq[];
  visit?: BlogVisit; // store block between the FAQ and the sources
  sources?: BlogSource[]; // "Sources" list after the FAQ (SEO audit build pass, D3)
};

export const POSTS: BlogPost[] = [];



export type BlogLocale = 'en';
export const postsFor = (_locale: BlogLocale = 'en') => POSTS;
export const getPost = (slug: string, locale: BlogLocale = 'en') => postsFor(locale).find((p) => p.slug === slug);
/** the three most recent other posts (newest first): every post cross-links the October 2026 posts and vice versa */
export const relatedPosts = (slug: string, locale: BlogLocale = 'en') =>
  postsFor(locale).filter((p) => p.slug !== slug).sort((a, b) => (a.datePublished < b.datePublished ? 1 : a.datePublished > b.datePublished ? -1 : 0)).slice(0, 3);
